Clase Marcador
    Privado Definir puntosLocal Como Entero;
    Privado Definir puntosVisitante Como Entero;

    Metodo Constructor()
        Este.puntosLocal <- 0;
        Este.puntosVisitante <- 0;
    FinMetodo

    Publico Metodo SumarLocal()
        Este.puntosLocal <- Este.puntosLocal + 1;
    FinMetodo

    Publico Metodo SumarVisitante()
        Este.puntosVisitante <- Este.puntosVisitante + 1;
    FinMetodo

    Publico Metodo Diferencia() Como Entero
        Retornar Este.puntosLocal - Este.puntosVisitante;
    FinMetodo
FinClase

Proceso EjecutarMarcador
    Definir golesLocal Como Entero;
    Definir golesVisitante Como Entero;
    Definir i Como Entero;
    Definir marcador Como Marcador;
    Leer golesLocal;
    Leer golesVisitante;
    marcador <- Nuevo Marcador();
    Para i <- 1 Hasta golesLocal Con Paso 1 Hacer
        marcador.SumarLocal();
    FinPara
    Para i <- 1 Hasta golesVisitante Con Paso 1 Hacer
        marcador.SumarVisitante();
    FinPara
    Escribir marcador.Diferencia();
FinProceso
